using System;using UnityEngine;
namespace LWS.TruckGiantSwing.Editor {public static class SwingFixtures {public static void Run(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Swing fixture "+label);n++;};check(SwingRules.Zone(new Vector3(0,0,29))==10,"ten");check(SwingRules.Zone(new Vector3(-5,0,46))==25,"twenty five");check(SwingRules.Zone(new Vector3(6,0,58))==50,"fifty");check(SwingRules.Zone(new Vector3(3,0,51))==100,"nearer precision hundred");check(SwingRules.Zone(new Vector3(3,0,53.3f))==100,"closed bullseye boundary");check(SwingRules.Zone(new Vector3(-5,0,39.9f))==0,"outside precision ring");check(SwingRules.Zone(new Vector3(14,0,36))==10,"closed rectangle corner");check(SwingRules.Zone(new Vector3(0,0,80))==0,"farther is not always better");check(SwingRules.Leaders(new[]{10,25,25},3,7)==6,"actual tied leaders");check(SwingRules.Leaders(new[]{100,25,50},3,6)==4,"tiebreak excludes other competitors");Debug.Log("SWING_RULE_FIXTURES_PASS count="+n);}}}
